//! Human explanations for RLPM failures. Keep technical error identities intact.
const diagnostics = @import("diagnostics");
const std = @import("std");

pub fn cause(err: anyerror) ?[]const u8 {
    return switch (err) {
        error.ConfigReadFailed => "The package configuration file could not be read. Check its path and permissions.",
        error.InvalidHookDirMode => "HookDirMode must be Append or Replace. Correct the value in the package configuration.",
        error.InvalidMigrationPolicy => "The file migration policy is invalid. Check the migration options in the package configuration.",
        error.ReadOnlyDatabase => "The package database is read-only for this operation. Use a writable installation database for package changes.",
        error.DatabaseLockFailed => "RLPM could not acquire or validate the package database lock. Check the database directory and filesystem state.",
        error.LockPermissionDenied => "RLPM does not have permission to lock the package database. Check the database directory permissions and authorization.",
        error.DownloadFailed, error.FileError => "The package or database download failed. Check the source, cache permissions, and preceding transfer details.",
        error.HostNotFound => "The download server name could not be resolved. Check the mirror hostname and DNS connection.",
        error.NotFound => "The requested download was not found at its source. Refresh the repository metadata and check the configured mirror.",
        error.SnapshotFailed => "RLPM could not create an immutable copy of the verified input. Check available resources and the source file.",
        error.FilesystemInspectionFailed => "RLPM could not inspect the destination filesystem. Check the reported path and its permissions.",
        error.RootConfinementUnavailable => "RLPM could not safely confine filesystem access to the installation root. Check platform support and the root path.",
        error.PathTypeConflict, error.DirectoryNotEmpty => "The destination path has a conflicting type or contains files that prevent replacement. Inspect the path before changing it.",
        error.CrossDeviceRename => "The file operation crosses filesystem boundaries where an atomic rename is required. Check the staging and destination locations.",
        error.FileDescriptorLimit => "RLPM reached the open-file limit. Check the process and system file descriptor limits.",
        error.HookFailed => "The package hook failed. Review its name, exit status, and output.",
        error.ScriptletFailed => "The package scriptlet failed. Review its function, exit status, and output; package setup may be incomplete.",
        error.LdconfigFailed => "Updating the shared-library cache failed. Review the ldconfig output and installation root.",
        error.ScriptletCleanupFailed => "Temporary scriptlet files could not be removed. Inspect the reported paths and permissions.",
        error.RepeatedHookOption => "The hook repeats an option that may appear only once. Correct the reported hook definition.",
        error.PostHookAbortIgnored => "A post-transaction hook requested an abort after package changes. Review its output; the completed changes cannot be aborted by this hook.",
        error.NetworkIsolationWarning => "The action worker could not apply the requested network isolation. Review the worker setup details.",
        error.ExtractionWarning => "The archive extractor reported a warning. Review the affected package and extraction output.",
        error.ConfigParseFailed => "The native package configuration could not be parsed. Check the reported configuration file.",
        error.InvalidParallelDownloads => "ParallelDownloads must be an integer from 1 to 255, greater than zero. Correct the value in the package configuration.",
        error.PreviewRootReadOnly => "Package changes cannot run against the temporary update-check root. Run the operation against the configured installation root.",
        error.DependencyPlanMismatch => "The resolved build dependencies do not match the required build environment. Review the expected packages, versions, and planned changes.",
        error.DatabaseNotFound, error.DbNotFound => "The requested package database is not configured. Check the repository name and configuration.",
        error.DatabaseReadFailed => "The package database could not be read. Check its path, permissions, and metadata.",
        error.DatabaseNotLoaded, error.IncompleteMetadata => "The package database does not have the metadata required for this operation. Refresh the repository databases.",
        error.InvalidDatabase, error.InvalidDatabaseEntry, error.InvalidSqliteDatabase, error.InvalidSnapshot => "The package database contains invalid metadata. Check the reported database before replacing or repairing it.",
        error.UnsupportedDatabaseVersion, error.UnsupportedDatabaseBackend => "This package database format is not supported by this RLPM version.",
        error.DatabaseAlreadyLoaded, error.DuplicateDatabase, error.DuplicatePackage => "A database or package identity is registered more than once. Check the repository configuration and database entries.",
        error.InvalidDatabaseName, error.ReservedDatabaseName => "The repository name is invalid or reserved. Correct its name in the package configuration.",
        error.DatabaseRecoveryRequired, error.InvalidPublicationJournal => "A previous database publication is incomplete or its recovery journal is invalid. Inspect the database and recovery files before making further package changes.",
        error.CacheBusy => "The package cache or database publication directory is in use. Wait for the other operation to finish.",
        error.DatabaseLocked, error.LockExists => "The package database is locked. Check for another running package manager before investigating a stale lock.",
        error.LockOwnershipLost, error.LockNotHeld, error.TransactionNotLocked => "RLPM no longer holds the required database lock. Inspect the database state before starting another transaction.",
        error.OwnerBusy, error.TransactionActive, error.CallbackReentry => "Another operation is active on this RLPM instance. Finish it before starting this operation.",
        error.ForeignOwner, error.StaleDatabaseReference, error.StalePackageReference => "The package or database reference is no longer valid for this RLPM instance. Repeat the query to obtain current metadata.",
        error.StaleDatabaseState, error.StaleFilesystemState, error.FileChanged => "The database or filesystem changed after RLPM inspected it. Review the affected state and resolve the transaction again.",
        error.InvalidTransactionState, error.InvalidActionState, error.TransactionNotInitialized, error.IncompletePreflight => "The transaction is not in the state required for this step. Report the operation and technical details if this persists.",
        error.InvalidTransactionFlags, error.InvalidMigrationFlags => "The requested transaction options are invalid or incompatible. Review the selected flags.",
        error.InvalidOption, error.ImmutablePath => "An RLPM configuration option is invalid or cannot be changed after initialization.",
        error.InvalidAnswer => "The confirmation response is invalid for the requested RLPM question.",
        error.CommitUnavailable, error.UnsupportedPackageOrigin => "This operation is not supported for the selected package source or transaction.",
        error.PackageIgnored => "The requested package is excluded by the ignore configuration. Review the ignored package or group before proceeding.",
        error.InvalidArchitecture => "The package architecture does not match the configured architectures. Select a compatible package.",
        error.DuplicateFilename => "Different packages resolve to the same archive filename. Check the conflicting repository entries.",
        error.FileConflicts => "A package file conflicts with another package or an existing filesystem entry. Review the affected paths and owners.",
        error.ChecksumMismatch => "The downloaded package or database does not match its expected checksum. Obtain a fresh copy from a trusted source.",
        error.ChecksumMissing => "The package metadata has no checksum required to verify this archive. Refresh the repository metadata or contact its maintainer.",
        error.SignatureMissing => "A required package or database signature is missing. Check that the source publishes its signature.",
        error.InvalidSignature, error.InvalidStatus => "The package or database signature could not be validated. Check the signing keys and obtain a valid signed copy; keep signature verification enabled.",
        error.SignatureTooLarge => "The signature exceeds RLPM's supported size limit. Check the source and signature file.",
        error.KeyAcquisitionUnavailable, error.InvalidKeySource => "The required signing key cannot be obtained from the configured key source. Check the key source and local keyring.",
        error.KeyImportDeclined => "The signing key import was declined, so the package or database could not be verified.",
        error.KeyImportFailed => "The signing key could not be imported. Check the keyring permissions and GPG output.",
        error.PackageIdentityMismatch, error.PackageMetadataMismatch => "The archive's package identity or metadata differs from the selected repository record. Refresh the metadata and obtain the matching archive.",
        error.DownloadWorkerFailed => "The package download worker failed. Check its output and that the Shelly executable can start its internal worker.",
        error.DownloadSandboxFailed => "The download sandbox could not be prepared. Check the configured download user and cache directory permissions.",
        error.DownloadSizeMismatch => "The downloaded file size differs from the expected size. Check the source and obtain a complete copy.",
        error.NoServers => "The repository has no configured servers. Check its Server entries and included mirror lists in the package configuration.",
        error.NotModified => "The server returned an unchanged response where RLPM required a usable local copy. Check the cached database or archive.",
        error.ArchiveFailed, error.ExtractionFailed => "The package or database archive could not be read or extracted. Check its format, integrity, and destination permissions.",
        error.InvalidArchiveEntry, error.DuplicateArchivePath => "The archive contains an invalid or duplicate entry. Obtain a corrected archive from its maintainer.",
        error.UnsafeArchivePath, error.UnsafeHardlink, error.UnsafeSymlink, error.UnsafeStagingDirectory => "The archive or staging directory contains an unsafe path or link. RLPM refused to use it; inspect the reported path and obtain a corrected package if needed.",
        error.InvalidHardlink, error.HardlinkTargetMissing => "An archive hard link has an invalid or missing target. Obtain a corrected package archive.",
        error.InvalidPkginfo, error.MissingPkginfo, error.MissingPackageVersion, error.InvalidMtree, error.InvalidXData => "The package archive has missing or invalid metadata. Obtain a corrected package archive.",
        error.InvalidPackageName, error.InvalidVersion, error.InvalidCharacter, error.InvalidPackageFilename, error.InvalidPackageRelation => "A package name, version, filename, or dependency expression is invalid. Check the reported metadata or target.",
        error.MetadataTooLarge, error.MetadataLineTooLong, error.PkginfoTooLarge, error.SizeExceeded => "The input exceeds RLPM's metadata or file size limit. Check the reported archive or metadata.",
        error.DuplicateValue, error.ValueOutsideSection => "The database metadata contains a duplicate value or a value outside its section. Obtain corrected metadata.",
        error.PackageArchiveRequired => "This operation requires a package archive. Select a complete package file.",
        error.InvalidBackup => "The package declares an invalid backup path or backup record. Check its package metadata.",
        error.InvalidMigrationMetadata, error.InvalidMigrationPath, error.InvalidMigrationSource, error.InvalidMigrationTarget, error.DuplicateMigration => "The package's file migration declarations are invalid or duplicated. Obtain corrected package metadata.",
        error.MigrationOwnershipConflict, error.MigrationTargetConflict, error.InvalidPackageOwnership => "The declared file migration conflicts with current file ownership or another target. Review the package and affected path.",
        error.MigrationNoExtractConflict => "A declared file migration conflicts with NoExtract. Review the migration and extraction configuration.",
        error.MigrationPathMissing => "A path required by the declared file migration is missing. Review the affected installation before proceeding.",
        error.UnsupportedMigrationVersion, error.UnsupportedMigrationBackup, error.UnsupportedMigrationType => "This RLPM version does not support the package's declared migration format or operation.",
        error.DiskSpaceInsufficient, error.CapacityUnavailable => "RLPM could not establish sufficient free space for the transaction. Check the destination filesystem and its available space.",
        error.ReadOnlyFilesystem => "The package destination is on a read-only filesystem. Check its mount configuration.",
        error.PathPermissionDenied => "RLPM cannot access a required path. Check the path and its permissions.",
        error.InvalidPath, error.InvalidRoot => "The configured root or package path is invalid. Check the reported path.",
        error.NotRegularFile => "RLPM expected a regular file at the reported path. Check its type before using it.",
        error.NotDirectory, error.ParentNotFound => "A required parent directory is missing or is not a directory. Check the destination path.",
        error.FilesystemWriteFailed, error.WriteFailed, error.SyncFailed => "RLPM could not write or synchronize package data. Check storage, permissions, and the affected installation state.",
        error.NameTooLong => "A required filesystem path exceeds the supported length. Check the package or configured directory paths.",
        error.AuditLogFailed => "RLPM could not write the package operation log. Check the log path, permissions, and free space.",
        error.ActionProtocolFailed, error.ActionTransportFailed, error.ActionRequestTooLarge => "RLPM could not communicate with its package action worker. Check the worker output and matching Shelly executable.",
        error.ScriptletTemporaryFailed => "RLPM could not prepare the temporary scriptlet files. Check the installation root and temporary directory permissions.",
        error.PreTransactionHookFailed => "A required pre-transaction hook failed. Review the hook name and output before proceeding.",
        error.HookDependencyMissing => "A package required by a hook is missing. Check the hook's dependency declarations.",
        error.InvalidHook, error.InvalidHookCommand, error.InvalidHookOption, error.InvalidHookSection, error.InvalidHookValue, error.IncompleteHookAction, error.IncompleteHookTrigger => "The package hook contains an invalid or incomplete definition. Correct the reported hook and line.",
        error.InvalidRegex => "The package search expression is invalid. Check its regular expression syntax.",
        error.IdentityExhausted, error.TooManyGroups, error.TooManyPackages => "The package database exceeds RLPM's supported identity or entry limits.",
        error.SystemInformationUnavailable, error.UnsupportedPlatform => "RLPM could not determine a supported system architecture. Check the host platform and configured architectures.",
        else => blk: {
            const shared = diagnostics.cause(err);
            break :blk if (std.mem.eql(u8, shared, diagnostics.unknown_cause)) null else shared;
        },
    };
}
